/**
 * sharepoint.js
 * Microsoft Graph API helpers for reading/writing SharePoint lists.
 * Uses MSAL browser (public client) — no backend required.
 *
 * Setup:
 * 1. npm install @azure/msal-browser
 * 2. Fill in clientId and tenantId from your Azure App Registration
 * 3. Import { initMsal, getRequests, updateRequestStatus } in App.jsx
 */
 
import { PublicClientApplication } from "@azure/msal-browser";
 
const MSAL_CONFIG = {
  auth: {
    clientId: "d7c2ae40-e776-4599-bed6-fddc8a86fdc6",
    authority: "https://login.microsoftonline.com/62e0afb6-8628-4cf2-9b52-498d8ab73de3",
    redirectUri: "https://mperkinslewis-bit.github.io/quote-tool",
  },
};
 
const GRAPH_SCOPES = ["https://graph.microsoft.com/Sites.ReadWrite.All"];
 
const SHAREPOINT_SITE_HOSTNAME = "62e0afb6-8628-4cf2-9b52-498d8ab73de3.sharepoint.com";
const SHAREPOINT_SITE_PATH = "/sites/RepsQuote";
const LIST_NAME = "QuoteRequests";
 
let msalInstance = null;
let siteId = null;
let listId = null;
 
export async function initMsal() {
  msalInstance = new PublicClientApplication(MSAL_CONFIG);
  await msalInstance.initialize();
  
  const response = await msalInstance.handleRedirectPromise();
  
  const accounts = msalInstance.getAllAccounts();
  if (accounts.length === 0) {
    await msalInstance.loginRedirect({ scopes: GRAPH_SCOPES });
  }
}
 
async function getToken() {
  const accounts = msalInstance.getAllAccounts();
  const result = await msalInstance.acquireTokenSilent({
    scopes: GRAPH_SCOPES,
    account: accounts[0],
  });
  return result.accessToken;
}
 
async function graphGet(path) {
  const token = await getToken();
  const res = await fetch(`https://graph.microsoft.com/v1.0${path}`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  return res.json();
}
 
async function graphPatch(path, body) {
  const token = await getToken();
  return fetch(`https://graph.microsoft.com/v1.0${path}`, {
    method: "PATCH",
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(body),
  });
}
 
async function getSiteAndListIds() {
  if (siteId && listId) return;

  const siteRes = await graphGet(
    `/sites/jkmayfair.sharepoint.com:/sites/RepsQuote`
  );
  siteId = siteRes.id;

  const listsRes = await graphGet(`/sites/${siteId}/lists`);
  const list = listsRes.value.find((l) => l.name === LIST_NAME);
  if (!list) throw new Error(`List "${LIST_NAME}" not found`);
  listId = list.id;
}
 
export async function getRequests() {
  await getSiteAndListIds();
  const res = await graphGet(
    `/sites/${siteId}/lists/${listId}/items?expand=fields&$top=100`
  );
  return res.value.map((item) => ({
    id: item.id,
    ...item.fields,
  }));
}
 
export async function updateRequestStatus(itemId, status, bouncedNotes = "") {
  await getSiteAndListIds();
  const fields = { Status: status };
  if (bouncedNotes) fields.BouncedNotes = bouncedNotes;
  await graphPatch(`/sites/${siteId}/lists/${listId}/items/${itemId}/fields`, fields);
}