// ─────────────────────────────────────────────
// ANTHROPIC API (via Cloudflare Worker proxy)
// ─────────────────────────────────────────────
async function callClaude(prompt) {
  const res = await fetch(CONFIG.WORKER_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      model: "claude-sonnet-4-5",
      max_tokens: 1000,
      messages: [{ role: "user", content: prompt }],
    }),
  });
  const data = await res.json();
  console.log("Claude response:", JSON.stringify(data));
  return data.content?.[0]?.text || "";
}

async function normaliseFishDescriptions(rawText) {
  const priceListDescriptions = PRICE_LIST.map(
    (p) => p.code + ": " + p.description
  ).join("\n");

  const prompt = "You are a seafood product matcher for a UK wholesale fish supplier.\n\n"
    + "Given this raw fish order text from a sales rep, extract each line item and match it to our standard price list where possible.\n\n"
    + "MATCHING RULES:\n"
    + "- Bass or sea bass fillet 140-160g matches BAR: SEA BASS PORTION 140/170G (EA)\n"
    + "- Dover sole fillet matches DVH: DOVER SOLE 18/20 WHOLE\n"
    + "- King prawns large matches SIO: TIGER PRAWNS FRESH 20/30 EC2S\n"
    + "- Numbers as words: one forty to one sixty = 140-160g\n"
    + "- Only set customPricing to true if there is genuinely no match on the price list\n"
    + "- If you find a match, set customPricing to false\n\n"
    + "RAW TEXT:\n" + rawText + "\n\n"
    + "STANDARD PRICE LIST:\n" + priceListDescriptions + "\n\n"
    + "Return ONLY a JSON array. Each element:\n"
    + '{"rawDescription":"original wording","matchedCode":"code or null","matchedDescription":"description or null","quantity":"number or null","unit":"unit or null","confidence":"high/medium/low","customPricing":true or false}';

  const raw = await callClaude(prompt);
  try {
    const cleaned = raw.replace(/^```[\w]*\n?/, "").replace(/\n?```$/, "").trim();
    return JSON.parse(cleaned);
  } catch {
    return [];
  }
}

// ─────────────────────────────────────────────
// QUOTE CALCULATION
// ─────────────────────────────────────────────
function calculateQuote(lineItems, deliveriesPerWeek, tier = "B") {
  const lines = lineItems.map((item) => {
    if (item.customPricing || !item.matchedCode) {
      // Custom pricing: flag for manual cost lookup
      return { ...item, unitPrice: null, lineTotal: null, isCustom: true };
    }
    const priceEntry = PRICE_LIST.find((p) => p.code === item.matchedCode);
    if (!priceEntry) return { ...item, unitPrice: null, lineTotal: null, isCustom: true };

    const price = priceEntry[`tier${tier}`];
    const qty = parseFloat(item.quantity) || 1;
    return {
      ...item,
      unitPrice: price,
      lineTotal: price * qty,
      isCustom: false,
    };
  });

  const knownTotal = lines
    .filter((l) => !l.isCustom && l.lineTotal)
    .reduce((sum, l) => sum + l.lineTotal, 0);

  const revenuePerDelivery = deliveriesPerWeek > 0 ? knownTotal / deliveriesPerWeek : 0;
  const belowMinimum = revenuePerDelivery > 0 && revenuePerDelivery < CONFIG.MIN_REVENUE_PER_DELIVERY;
  const hasCustomItems = lines.some((l) => l.isCustom);

  return { lines, knownTotal, revenuePerDelivery, belowMinimum, hasCustomItems, tier };
}

